580:       if (day === 12) events.push({ day, kind: 'phase', title: 'Crecimiento', note: 'Raíces establecidas. Primer riego medido por peso de maceta.' });
581:       if (day === 18) events.push({ day, kind: 'event', title: 'Primer LST', note: 'Apertura suave de la canopia; se registra la respuesta a 48 h.' });
582:       if (day === 27) events.push({ day, kind: 'phase', title: 'Prefloración', note: 'La fórmula cambia a floración y la humedad baja hacia 58%.' });
583:       if (day === 34 && vpdAlerts > 3) events.push({ day, kind: 'alert', title: 'VPD fuera de rango', note: 'Tres lecturas seguidas por encima de 1,8 kPa. Se intensifica la ventilación.' });
584:       if (day === 37) events.push({ day, kind: 'phase', title: 'Floración', note: 'Cogollos visibles. Se prioriza estabilidad y prevención de botritis.' });
585:       if (day === 44 && cfg.id === 'intensive') events.push({ day, kind: 'event', title: 'Defoliación selectiva', note: 'Solo hojas que bloquean luz. La estrategia intensiva paga más insumos.' });
586:       if (day === 52) events.push({ day, kind: 'event', title: 'Pico de demanda', note: 'Consumo de agua máximo del batch. La reserva se repone a tiempo.' });
587:       if (day === 57) events.push({ day, kind: 'phase', title: 'Maduración', note: 'Tricomas lechosos. Se reduce riego y nutrición.' });
588:       if (day === 63) events.push({ day, kind: 'alert', title: 'Riesgo de botritis', note: 'Humedad alta en el interior de cogollos: sube la ventilación.' });
589:       if (day === 67) events.push({ day, kind: 'phase', title: 'Ventana de corte', note: 'Empieza la ventana de cosecha. Se revisa tricoma por planta.' });
