596:       const q = Math.max(.4, Math.min(1.1, p.health / 88));
597:       yieldG += Math.round(55 * q * cfg.quality * (1 + Math.min(.06, (p.age - 67) * .002)));
598:     });
599:     // La cosecha se registra en el día de corte; el costo acumulado ya incluye el ciclo completo.
600:     events.push({ day: harvestDay, kind: 'harvest', title: `Cosecha · ${yieldG} g`, note: `${harvests} plantas cerraron el batch y se registró el peso por lote.` });
