842:   function simulateFull(cfg, seedOffset = 0) {
843:     const st = window.STRAINS.find(x => x.id === cfg.strainId) || window.STRAINS[0];
844:     const strat = BATCH_STRATEGIES.find(s => s.id === cfg.strategy) || BATCH_STRATEGIES[0];
845:     const days = cfg.days;
846:     const baseYieldPerPlant = st.yield || 85;
847:     const cycleFactor = Math.max(.7, Math.min(1.15, cfg.days / (st.flower + 5)));
848:     const lightFactor = Math.max(.78, Math.min(1.12, cfg.light / 18));
849:     const tempPenalty = Math.max(0, Math.abs(cfg.temp - 24) - 2) * 1.1;
850:     const rand = seededRandom((cfg.strainId.charCodeAt(0) || 7) * 131 + days * 17 + cfg.plants * 911 + (cfg.strategy === 'balanced' ? 7 : cfg.strategy.length * 31) + seedOffset);
851:     const growth = [], healthS = [], moistureS = [], nutritionS = [], yieldS = [];
852:     let health = 92, moisture = 58, nutrition = 55, stressDays = 0;
853:     for (let d = 1; d <= days; d++) {
854:       const phaseT = d / days;
855:       const logistic = 100 / (1 + Math.exp(-(d - days * 0.52) / (days * 0.16)));
856:       growth.push(Math.round(Math.min(100, Math.max(4, logistic + (rand() - .5) * 3))));
857:       moisture = Math.max(18, Math.min(88, moisture - 11 + rand() * 5 + (strat.waterAt > 30 ? 4 : 0)));
858:       if (moisture < strat.waterAt) moisture = Math.min(88, moisture + 34);
859:       nutrition = Math.max(15, Math.min(90, nutrition - 2.1 + rand() * 2 + (strat.feedAt > 30 ? 3 : 0)));
860:       if (nutrition < strat.feedAt) nutrition = Math.min(90, nutrition + 30);
861:       let stress = 0;
862:       if (moisture < 22 || moisture > 84) stress += 5;
863:       if (nutrition < 18) stress += 4;
864:       if (tempPenalty > 2) stress += Math.min(4, tempPenalty / 2);
865:       // Variación sintética entre corridas para enseñar sensibilidad; no es una tasa empírica.
866:       if (rand() < 0.08) stress += 3 + rand() * 5;
867:       if (strat.stress && d % (strat.stressEvery || 3) === 0) stress += strat.stress;
868:       health = Math.max(15, Math.min(99, health + (stress ? -stress : 0.55)));
869:       if (stress) stressDays++;
870:       if (d % 7 === 0 && health < 55) stressDays++;
871:       healthS.push(Math.round(health));
872:       moistureS.push(Math.round(moisture));
873:       nutritionS.push(Math.round(nutrition));
874:       const frac = Math.max(0, Math.min(1, (d - 1) / Math.max(1, days - 1)));
875:       yieldS.push(Math.round(baseYieldPerPlant * cfg.plants * cycleFactor * lightFactor * (health / 92) * Math.pow(frac, 1.6)));
876:     }
877:     const yieldG = yieldS[yieldS.length - 1] || 0;
878:     const potential = Math.round(baseYieldPerPlant * cfg.plants * cycleFactor * lightFactor);
879:     const yieldScore = potential ? Math.min(100, Math.round(yieldG / potential * 100)) : 0;
880:     const avgHealth = Math.round(healthS.reduce((a, b) => a + b, 0) / healthS.length);
881:     const healthScore = Math.max(0, Math.min(100, Math.round(avgHealth)));
882:     const stability = Math.max(0, Math.min(100, 100 - stressDays * 2.2 - tempPenalty * 3));
883:     const spentDaily = 4500 * (cfg.light / 18) + (strat.premium > 0 ? 1600 : strat.premium < 0 ? -250 : 650);
884:     const spent = Math.round(spentDaily * days + cfg.plants * 1200);
885:     const perGram = yieldG ? Math.round(spent / yieldG) : spent;
886:     const costScore = Math.max(0, Math.min(100, Math.round((2200 - perGram) / 16)));
887:     const score = Math.max(0, Math.min(100, Math.round(yieldScore * .4 + costScore * .2 + healthScore * .25 + stability * .15)));
888:     const grade = gradeFor(score);
