848:     const lightFactor = Math.max(.78, Math.min(1.12, cfg.light / 18));
849:     const tempPenalty = Math.max(0, Math.abs(cfg.temp - 24) - 2) * 1.1;
850:     const rand = seededRandom((cfg.strainId.charCodeAt(0) || 7) * 131 + days * 17 + cfg.plants * 911 + (cfg.strategy === 'balanced' ? 7 : cfg.strategy.length * 31) + seedOffset);
